<?php
namespace App\Features\Stock\Livewire;
use Livewire\Component;use Livewire\WithPagination;use Livewire\WithFileUploads;use App\Features\Stock\Models\Stock;use App\Features\Stock\Services\StockService;use App\Features\Stock\Services\StockExcelService;use App\Features\Ai\Contracts\AiClientInterface;use App\Features\Stock\Enums\StockStatus;use Illuminate\Support\Facades\Storage;
class StockList extends Component {use WithPagination,WithFileUploads;protected string $paginationTheme='tailwind';public string $search='';public string $status='';public bool $showForm=false;public ?int $editingId=null;public string $name='',$sku='',$description='',$unit='pcs';public int $quantity=0,$min_stock=5;public $price=null;public $excelFile;public string $aiPrompt='';public int $aiCount=5;public array $generated=[];public function updatingSearch(){ $this->resetPage(); }public function create(){ $this->resetForm();$this->showForm=true;}public function edit(int $id){$s=Stock::where('user_id',auth()->id())->findOrFail($id);$this->editingId=$s->id;foreach(['name','sku','description','unit','quantity','min_stock','price'] as $f)$this->$f=$s->$f;$this->showForm=true;}private function resetForm(){ $this->reset(['editingId','name','sku','description','price']);$this->quantity=0;$this->min_stock=5;$this->unit='pcs';$this->resetValidation();}public function save(StockService $service){$data=$this->validate(['name'=>'required|string|max:150','sku'=>'nullable|string|max:80','description'=>'nullable|string|max:10000','quantity'=>'required|integer|min:0','unit'=>'required|string|max:30','price'=>'nullable|numeric|min:0','min_stock'=>'required|integer|min:0']);if($this->editingId){$s=Stock::where('user_id',auth()->id())->findOrFail($this->editingId);$service->update($s,$data);}else{$service->create(auth()->id(),$data);} $this->showForm=false;$this->resetForm();session()->flash('success','Data stok berhasil disimpan.');}public function adjust(int $id,int $delta,StockService $service){$s=Stock::where('user_id',auth()->id())->findOrFail($id);try{$service->adjust($s,$delta);session()->flash('success','Jumlah stok berhasil diperbarui.');}catch(\DomainException $e){$this->addError('quantity',$e->getMessage());}}public function delete(int $id,StockService $service){$s=Stock::where('user_id',auth()->id())->findOrFail($id);$service->delete($s);session()->flash('success','Barang berhasil dihapus.');}public function export(StockExcelService $excel){$path=$excel->export(auth()->id());return response()->download($path,'stock-export.xlsx')->deleteFileAfterSend(true);}public function import(StockExcelService $excel){$this->validate(['excelFile'=>'required|file|mimes:xlsx,xls,csv|max:5120']);$path=$this->excelFile->getRealPath();$count=$excel->import($path,auth()->id());$this->reset('excelFile');session()->flash('success',"{$count} barang berhasil diimpor.");}public function generate(AiClientInterface $ai){$this->validate(['aiPrompt'=>'required|string|max:500','aiCount'=>'required|integer|min:1|max:20']);try{$this->generated=$ai->generate($this->aiPrompt,$this->aiCount);}catch(\Throwable $e){$this->addError('aiPrompt',app()->hasDebugModeEnabled()?$e->getMessage():'AI tidak dapat dihubungi. Periksa konfigurasi API.');}}public function saveGenerated(int $index,StockService $service){$item=$this->generated[$index]??null;if(!$item)return;$data=['name'=>$item['name'],'sku'=>$item['sku']??null,'description'=>$item['description']??null,'quantity'=>max(0,(int)($item['quantity']??0)),'unit'=>$item['unit']??'pcs','price'=>isset($item['price'])?(float)$item['price']:null,'min_stock'=>max(0,(int)($item['min_stock']??5))];$service->create(auth()->id(),$data);unset($this->generated[$index]);session()->flash('success','Item AI disimpan.');}public function render(){ $stocks=Stock::where('user_id',auth()->id())->when($this->search,fn($q)=>$q->where(fn($x)=>$x->where('name','like','%'.$this->search.'%')->orWhere('sku','like','%'.$this->search.'%')))->when($this->status,fn($q)=>$q->where('status',$this->status))->latest()->paginate(10);return view('livewire.stock.stock-list',['stocks'=>$stocks,'statuses'=>StockStatus::cases()])->layout('components.layouts.app');}}
